import{z as l,x as A,o as E,c as p,q as r,j as i,D as e,d as n,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"回购市场与融资","description":"","frontmatter":{"title":"回购市场与融资","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/repo-funding.md","filePath":"quant/repo-funding.md","lastUpdated":1791063341000}'),s={name:"quant/repo-funding.md"};function d(h,a,u,c,m,D){const t=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=r('<h1 id="回购市场与融资" tabindex="-1">回购市场与融资 <a class="header-anchor" href="#回购市场与融资" aria-label="Permalink to &quot;回购市场与融资&quot;">​</a></h1><div class="epigraph"><p>回购用证券换现金并约定买回：它是短期利率的实现场所，也是杠杆的管道。特殊券与一般抵押品把同一国债分成两种融资价格。</p><footer>—— Gorton and Metrick, Securitized Banking and the Run on Repo, JFE, 2012；Krishnamurthy, Nagel and Orlov, Sizing Up Repo, Journal of Finance, 2014；对照 Tuckman 对回购与融资的教科书处理</footer></div><p><a href="/quant/securities-lending">上一课</a>把券的租用停在借券。<a href="/quant/fi-relative-value">固收 RV</a>已预告杠杆在 repo。本课的缺口是<strong>现金腿</strong>：回购（repo）与逆回购如何决定杠杆成本、折算率（haircut）与挤兑。Gorton 与 Metrick（2012）把 2007–09 的回购挤兑写成证券化银行的运行；Krishnamurthy、Nagel 与 Orlov（2014）从规模上校准「回购市场有多大」。后课期权到期会用到融资与保证金的同一条现金约束。中国银行间回购在债市进阶课续写，本课给一般机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>买入持有国债的经济收益，必须减去融资：用该券做抵押借现金的利率。GC repo 利率跟踪政策利率与准备金；特殊券 repo 利率可以显著更低（现金出借人为拿到特定券而接受更低利息）。对空头，特殊性表现为难以借到券或必须支付借券费；对多头融资，特殊性表现为更便宜的融资——同一现象的两面。问题是 RV 与基差交易的「中性」建立在 repo 曲线可滚动；一旦 haircut 上调或对手停止展期，杠杆被抽走，残差变成方向，与 1998、2008、2020 的路径一致。</p><p><span class="marginnote">代个数字：1 亿元国债，GC 回购利率 5%、该券的特殊 repo 利率 3%。用它做抵押融资一年，利息差 2 个百分点就是 200 万元——这是「特殊性」给多头的融资补贴。空头那边，借同一只券要付借券费，费率通常与这段利差互相映照：一笔券的两端必须用同一条利率曲线核对，否则 RV 的「中性」是假的。</span></p>',6)),(E(),i(B,null,{default:e(()=>[o(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E5%8F%AA%E8%A2%AB%E8%BF%BD%E6%8D%A7%E7%9A%84%E5%9B%BD%E5%80%BA%22%5D%20--%3E%20L%5B%22%E5%A4%9A%E5%A4%B4%3A%20%E6%8B%BF%E5%AE%83%E5%81%9A%E6%8A%B5%E6%8A%BC%E8%9E%8D%E8%B5%84%22%5D%0A%20%20S%20--%3E%20SH%5B%22%E7%A9%BA%E5%A4%B4%3A%20%E6%83%B3%E5%80%9F%E5%AE%83%E5%8D%96%E5%87%BA%22%5D%0A%20%20L%20--%3E%20LP%5B%22%E7%89%B9%E6%AE%8A%20repo%20%E5%88%A9%E7%8E%87%E6%9B%B4%E4%BD%8E%3A%20%E8%9E%8D%E8%B5%84%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20SH%20--%3E%20SHP%5B%22%E5%80%9F%E5%88%B8%E8%B4%B9%E6%9B%B4%E9%AB%98%3A%20%E5%80%9F%E5%85%A5%E8%A6%81%E4%BB%98%E8%B4%B9%22%5D%0A%20%20LP%20--%3E%20BOTH%5B%22%E5%90%8C%E4%B8%80%E7%A8%80%E7%BC%BA%E6%80%A7%E7%9A%84%E4%B8%A4%E9%9D%A2%22%5D%0A%20%20SHP%20--%3E%20BOTH%0A%20%20BOTH%20--%3E%20RV%5B%22RV%20%E4%B8%8E%E5%9F%BA%E5%B7%AE%E5%AE%9A%E4%BB%B7%E5%BF%85%E9%A1%BB%E7%94%A8%E5%AF%B9%E5%88%A9%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>期限：隔夜、远期起息、定期。隔夜滚动有展期风险；定期锁定成本但占用授信。三方回购经清算银行，双边回购对手集中度更高。折算率随波动与券种跳升时，同样的组合突然需要更多自有现金——这是去杠杆的机械通道，不是「模型算错久期」。</p><h3 id="回购挤兑与-ccp-保证金同时抽现金" tabindex="-1">回购挤兑与 CCP 保证金同时抽现金 <a class="header-anchor" href="#回购挤兑与-ccp-保证金同时抽现金" aria-label="Permalink to &quot;回购挤兑与 CCP 保证金同时抽现金&quot;">​</a></h3><p>危机里 VM、haircut、基金赎回可以同日要钱。只对冲利率 DV01、不对冲融资流动性，账上中性、现金上爆。Adrian 与 Shin 一类工作强调经销商杠杆的亲周期性；本课只要把 haircut 与展期当成状态变量进回测情景，而不是把 repo 利率当常数利差。</p><p><span class="marginnote">美国 ON RRP、中国银行间质押式回购、交易所标准券回购，法律结构不同，经济同构：抵押、折算、到期买回。不要用一个 ticker 的回购利率去贴现所有市场。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每笔需要融资的持仓标注：抵押券、haircut、利率、到期、对手或 CCP。滚动假设必须显式：每日展期 vs 锁定期限。压力情景：haircut +5～20 个百分点、GC 利率跳升、特殊券变为 GC（融资优势消失）、对手授信削减。容量先满在授信与合格抵押，而不是在债券 DV01。与<a href="/quant/settlement-fails">结算失败</a>联动：缺券 fail 会破坏 repo 交割，融资与借券互相咬住。</p><p><span class="marginnote">这一步如果省了，压力测试会漏掉真正的爆点：2008 与 2020 年，多数杠杆策略不是死在方向，而是死在 haircut 上调 5～20 个百分点与对手削减授信同时发生。融资流动性对冲不了 DV01——账面利率中性、现金链断裂，是机构倒下的标准形态。</span></p><p>会计：回购是抵押融资还是卖出，影响杠杆展示，不影响经济风险。研究应按经济暴露记账。ETF 与期货的隐含融资应与 repo 对照，找出便宜的杠杆管道，同时计入基差与保证金。</p><h3 id="特殊性进入定价" tabindex="-1">特殊性进入定价 <a class="header-anchor" href="#特殊性进入定价" aria-label="Permalink to &quot;特殊性进入定价&quot;">​</a></h3><p>持有成本模型里，特殊券的 repo 利率替换一般 \\(r\\)。期现、债券期货 CTD、股票融资盘都应对 \\(r\\) 选用对的那个。用国债 GC 去贴现公司债 RV，融资项会系统性偏。点-in-time 的特殊性清单与借券清单一样，属于研究基础设施。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回购把证券变成货币弹性：高信用抵押品几乎是钱，haircut 小；一旦抵押品信息变差，haircut 跳升，弹性消失，出现挤兑。这与 CCP 瀑布不同：可以发生在双边或三方，不必等正式违约。对量化：杠杆策略的真实风险预算是「融资市场仍愿意以昨日条款展期」的概率。该概率在平静期接近 1，在压力期不是。</p><p><span class="marginnote">「高信用抵押品几乎是钱」的直觉类比：国债像一张人人都认的储值卡，回购就是把卡押出去换现金，haircut 是兑换折扣。市场一旦怀疑卡片成色，折扣一夜加深，卡的「钱性」蒸发——所以回购挤兑是货币性事件，不必等发行人违约，也不必等价格崩盘。</span></p><p>与撮合的距离：repo 多数不在股票 LOB 上交易，而在双边、电子平台或交易所回购。微观结构课的价差公式不能直接套；深度应以授信与券源计。不要把股票 tick 图拿来画回购流动性。</p>',14)),(E(),i(B,null,{default:e(()=>[o(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Bond%5B%22%E6%8C%81%E6%9C%89%E8%AF%81%E5%88%B8%22%5D%20--%3E%20Repo%5B%22%E6%8A%B5%E6%8A%BC%E8%9E%8D%E8%B5%84%22%5D%0A%20%20Repo%20--%3E%20Cash%5B%22%E7%8E%B0%E9%87%91%E6%9D%A0%E6%9D%86%22%5D%0A%20%20Hair%5B%22%E6%8A%98%E7%AE%97%E7%8E%87%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20More%5B%22%E8%BF%BD%E5%8A%A0%E8%87%AA%E6%9C%89%E7%8E%B0%E9%87%91%22%5D%0A%20%20Roll%5B%22%E6%8B%92%E7%BB%9D%E5%B1%95%E6%9C%9F%22%5D%20--%3E%20Liq%5B%22%E5%BC%BA%E5%88%B6%E5%87%8F%E4%BB%93%22%5D%0A%20%20Spec%5B%22%E7%89%B9%E6%AE%8A%E5%88%B8%22%5D%20--%3E%20Cheap%5B%22%E6%9B%B4%E4%BD%8E%E8%9E%8D%E8%B5%84%E5%88%A9%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用客户托管券违规加杠杆、或隐瞒回购杠杆的做法。<a href="/quant/fi-relative-value">固收 RV</a>已声明边界。主权债、信用债、股票质押式回购的合格性与监管资本权重不同，不能一个 haircut 打天下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回购是杠杆与短期利率的实现；GC 与特殊券是两种价格。</li><li>容量与爆仓首先来自 haircut 与展期，不是来自 DV01 算错。</li><li>融资条款必须点-in-time 进回测，常数利差会低估危机。</li><li>出处：Gorton and Metrick, <em>JFE</em>, 2012；Krishnamurthy, Nagel and Orlov, <em>JF</em>, 2014。</li></ul>',4))])}const C=l(s,[["render",d]]);export{f as __pageData,C as default};
